  8	use vexel_geometry::{affine_compose, affine_identity, affine_map_point};
  9	use vexel_scene::{
 10	    Affine, Diagnostic, Edge, ErrorKind, EvaluatedFrame, FrameBuilder, LimitKind, Paint, PaintKind,
