 18	const CHAIN_MAX: usize = 128;
 19	const WORK_MAX: usize = 50_000_000;
 20	/// Default owned-frame byte ceiling, matching the original animation clip cap.
 21	pub const DEFAULT_FRAME_BYTE_BUDGET: usize = 64 * 1024 * 1024;
 22	
 23	fn diag(kind: ErrorKind, offset: usize) -> Diagnostic {
 24	    Diagnostic { kind, offset }
 25	}
 26	fn invalid(offset: usize) -> Diagnostic {
 27	    diag(ErrorKind::InvalidArgument, offset)
 28	}
 29	fn limit(kind: LimitKind) -> Diagnostic {
 30	    diag(ErrorKind::Limit(kind), 0)
 31	}
 32	fn arithmetic() -> Diagnostic {
 33	    limit(LimitKind::Arithmetic)
 34	}
 35	fn oom() -> Diagnostic {
 36	    diag(ErrorKind::OutOfMemory, 0)
 37	}
 38	fn charge(control: &mut dyn WorkControl, amount: usize) -> Result<()> {
 39	    let units = u64::try_from(amount).map_err(|_| arithmetic())?;
 40	    control
 41	        .charge(WorkKind::AnimationTransform, units)
 42	        .map_err(|s| match s {
 43	            vexel_scene::Stop::Canceled => diag(ErrorKind::Canceled, 0),
 44	            vexel_scene::Stop::Limit => limit(LimitKind::Work),
 45	            vexel_scene::Stop::Overflow => arithmetic(),
 46	        })
 47	}
 48	fn count_work(work: &mut usize, amount: usize) -> Result<()> {
 49	    *work = work.checked_add(amount).ok_or_else(arithmetic)?;
 50	    if *work > WORK_MAX {
 51	        return Err(limit(LimitKind::Work));
 52	    }
 53	    Ok(())
 54	}
 55	fn changes_clips(track: &Track, item: OverlayItem) -> bool {
 56	    matches!(track.kind, Kind::Transform | Kind::Motion)
 57	        || (matches!(track.kind, Kind::Animate | Kind::Set)
 58	            && item.value.kind == ValueKind::Number
 59	            && matches!(
 60	                track.attribute,
 61	                Attribute::X
 62	                    | Attribute::Y
 63	                    | Attribute::Cx
 64	                    | Attribute::Cy
 65	                    | Attribute::Width
 66	                    | Attribute::Height
 67	                    | Attribute::Rx
 68	                    | Attribute::Ry
 69	                    | Attribute::R
 70	            ))
 71	}
 72	fn copy_table<T: Copy>(values: &[T], control: &mut dyn WorkControl) -> Result<Vec<T>> {
 73	    let mut copy = Vec::new();
 74	    copy.try_reserve_exact(values.len()).map_err(|_| oom())?;
 75	    for value in values {
 76	        control
 77	            .charge(WorkKind::AnimationTransform, 1)
 78	            .map_err(|s| match s {
 79	                vexel_scene::Stop::Canceled => diag(ErrorKind::Canceled, 0),
 80	                vexel_scene::Stop::Limit => limit(LimitKind::Work),
 81	                vexel_scene::Stop::Overflow => arithmetic(),
 82	            })?;
 83	        copy.push(*value);
 84	    }
 85	    Ok(copy)
 86	}
