 88	fn inverse(m: Affine, threshold: f64) -> Option<Affine> {
 89	    let determinant = m.a * m.d - m.b * m.c;
 90	    if !determinant.is_finite() || determinant.abs() < threshold {
 91	        return None;
 92	    }
 93	    let k = 1.0 / determinant;
 94	    let out = Affine {
 95	        a: m.d * k,
 96	        b: -m.b * k,
 97	        c: -m.c * k,
 98	        d: m.a * k,
 99	        e: (m.c * m.f - m.d * m.e) * k,
100	        f: (m.b * m.e - m.a * m.f) * k,
101	    };
102	    vexel_geometry::affine_valid(out).then_some(out)
103	}
104	fn transform_value(track: &Track, value: Value) -> Option<Affine> {
105	    let x = value.number[0];
106	    let y = value.number[1];
107	    if !x.is_finite() || !y.is_finite() || x.abs() > 1e6 || y.abs() > 1e6 {
108	        return None;
109	    }
110	    let mut m = affine_identity();
111	    match track.transform_type {
112	        TransformType::Translate => {
113	            m.e = x;
114	            m.f = y;
115	        }
116	        TransformType::Scale => {
117	            m.a = x;
118	            m.d = if value.number[3] >= 2. { y } else { x };
119	        }
120	        TransformType::Rotate => {
121	            let angle = x * 0.017453292519943295769;
122	            let (s, c) = angle.sin_cos();
123	            if !s.is_finite() || !c.is_finite() {
124	                return None;
125	            }
126	            m = Affine {
127	                a: c,
128	                b: s,
129	                c: -s,
130	                d: c,
131	                e: 0.,
132	                f: 0.,
133	            };
134	            if value.number[3] >= 3. {
135	                let to = Affine {
136	                    e: value.number[1],
137	                    f: value.number[2],
138	                    ..affine_identity()
139	                };
140	                let from = Affine {
141	                    e: -value.number[1],
142	                    f: -value.number[2],
143	                    ..affine_identity()
144	                };
145	                m = affine_compose(affine_compose(to, m)?, from)?;
146	            }
147	        }
148	        TransformType::SkewX | TransformType::SkewY => {
149	            let t = (x * 0.017453292519943295769).tan();
150	            if !t.is_finite() || t.abs() > 1e6 {
151	                return None;
152	            }
153	            if track.transform_type == TransformType::SkewX {
154	                m.c = t
155	            } else {
156	                m.b = t
157	            }
158	        }
159	    }
160	    vexel_geometry::affine_valid(m).then_some(m)
161	}
162	fn product(
163	    transforms: &[TransformFrame],
164	    shape: &Shape,
165	    control: &mut dyn WorkControl,
166	    work: &mut usize,
167	) -> Result<Affine> {
168	    let mut chain = [None; CHAIN_MAX];
169	    let mut count = 0;
170	    let mut node = shape.source.transform_node;
171	    while let Some(id) = node {
172	        if count == CHAIN_MAX || id.index() >= transforms.len() {
173	            return Err(invalid(shape.source.element.start));
174	        }
175	        charge(control, 1)?;
176	        *work = work.checked_add(1).ok_or_else(arithmetic)?;
177	        if *work > WORK_MAX {
178	            return Err(limit(LimitKind::Work));
179	        }
180	        chain[count] = Some(id);
181	        count += 1;
182	        node = transforms[id.index()].parent;
183	    }
184	    let mut out = affine_identity();
185	    while count > 0 {
186	        count -= 1;
187	        let n = transforms[chain[count].ok_or_else(|| invalid(0))?.index()];
188	        let local = affine_compose(n.attribute, n.suffix)
189	            .and_then(|m| affine_compose(n.motion, m))
190	            .ok_or_else(|| invalid(n.source_offset))?;
191	        out = affine_compose(out, local).ok_or_else(|| invalid(n.source_offset))?;
192	    }
193	    Ok(out)
194	}
195	fn shape_bounds(
196	    shape: &Shape,
197	    current_edges: &[Edge],
198	    inverse: Affine,
199	    control: &mut dyn WorkControl,
200	    work: &mut usize,
201	) -> Result<[f64; 4]> {
202	    let edges = shape
203	        .edges
204	        .slice(current_edges)
205	        .ok_or_else(|| invalid(shape.source.element.start))?;
206	    if edges.is_empty() {
207	        return Err(invalid(shape.source.element.start));
208	    }
209	    charge(control, edges.len())?;
210	    *work = work.checked_add(edges.len()).ok_or_else(arithmetic)?;
211	    if *work > WORK_MAX {
212	        return Err(limit(LimitKind::Work));
213	    }
214	    let p = affine_map_point(inverse, edges[0].a).ok_or_else(|| invalid(0))?;
215	    let mut b = [p.x, p.y, p.x, p.y];
216	    for edge in edges {
217	        for point in [edge.a, edge.b] {
218	            let q = affine_map_point(inverse, point).ok_or_else(|| invalid(0))?;
219	            b[0] = b[0].min(q.x);
220	            b[1] = b[1].min(q.y);
221	            b[2] = b[2].max(q.x);
222	            b[3] = b[3].max(q.y);
223	        }
224	    }
225	    Ok(b)
226	}
227	fn map_shape_edges(
228	    view: SceneView<'_>,
229	    shape: &Shape,
230	    matrix: Affine,
231	    edges: &mut [Edge],
232	    control: &mut dyn WorkControl,
233	    work: &mut usize,
234	) -> Result<()> {
235	    let range = shape.edges;
236	    let end = range.end().ok_or_else(arithmetic)?;
237	    if end > edges.len() {
238	        return Err(invalid(shape.source.element.start));
239	    }
240	    charge(control, range.count)?;
241	    *work = work.checked_add(range.count).ok_or_else(arithmetic)?;
242	    if *work > WORK_MAX {
243	        return Err(limit(LimitKind::Work));
244	    }
245	    for edge in &mut edges[range.first..end] {
246	        edge.a = affine_map_point(matrix, edge.a).ok_or_else(|| invalid(0))?;
247	        edge.b = affine_map_point(matrix, edge.b).ok_or_else(|| invalid(0))?;
248	    }
249	    let _ = view;
250	    Ok(())
251	}
