536	fn has_effect(
537	    view: SceneView<'_>,
538	    shape: usize,
539	    control: &mut dyn WorkControl,
540	    work: &mut usize,
541	) -> Result<bool> {
542	    for g in view.groups {
543	        charge(control, 1)?;
544	        *work = work.checked_add(1).ok_or_else(arithmetic)?;
545	        if *work > WORK_MAX {
546	            return Err(limit(LimitKind::Work));
547	        }
548	        if shape >= g.shapes.first
549	            && shape < g.shapes.end().ok_or_else(arithmetic)?
550	            && (g.filter.is_some() || g.mask.is_some())
551	        {
552	            return Ok(true);
553	        }
554	    }
555	    Ok(false)
556	}
