558	#[cfg(test)]
559	mod tests {
560	    use super::*;
561	    use vexel_svg_animation::{Kind, Track, TransformType, Value};
562	
563	    fn track(transform_type: TransformType) -> Track {
564	        Track {
565	            kind: Kind::Transform,
566	            transform_type,
567	            ..Track::default()
568	        }
569	    }
570	
571	    #[test]
572	    fn transform_matrix_keeps_svg_order_and_rotation_center() {
573	        let mut value = Value::default();
574	        value.number = [12.0, 3.0, 4.0, 3.0];
575	        let m = transform_value(&track(TransformType::Rotate), value).unwrap();
576	        assert!((m.a - 12f64.to_radians().cos()).abs() < 1e-12);
577	        assert!((m.b - 12f64.to_radians().sin()).abs() < 1e-12);
578	        assert!((m.e - (3.0 - m.a * 3.0 - m.c * 4.0)).abs() < 1e-12);
579	        assert!((m.f - (4.0 - m.b * 3.0 - m.d * 4.0)).abs() < 1e-12);
580	    }
581	
582	    #[test]
583	    fn transform_matrix_preserves_translate_scale_and_skew_components() {
584	        let mut value = Value::default();
585	        value.number = [3.0, -4.0, 0.0, 2.0];
586	        let translated = transform_value(&track(TransformType::Translate), value).unwrap();
587	        assert_eq!((translated.e, translated.f), (3.0, -4.0));
588	
589	        value.number = [2.0, 3.0, 0.0, 2.0];
590	        let scaled = transform_value(&track(TransformType::Scale), value).unwrap();
591	        assert_eq!((scaled.a, scaled.d), (2.0, 3.0));
592	
593	        value.number = [45.0, 0.0, 0.0, 1.0];
594	        let skew_x = transform_value(&track(TransformType::SkewX), value).unwrap();
