388	/// Update clip owner inverses and object-bounding-box bounds for one shape's
389	/// complete instance-specific transform ancestry. Publication is atomic.
390	pub fn update_animation_clips(
391	    frame: &mut EvaluatedFrame<'_>,
392	    shape: ShapeId,
393	    update_bounds: bool,
394	    control: &mut dyn WorkControl,
395	) -> Result<()> {
396	    let view = frame.view();
397	    if view.clips.is_empty() {
398	        return Err(invalid(0));
399	    }
400	    control.checkpoint().map_err(|s| match s {
401	        vexel_scene::Stop::Canceled => Diagnostic {
402	            kind: ErrorKind::Canceled,
403	            offset: 0,
404	        },
405	        vexel_scene::Stop::Limit => limit(LimitKind::Work),
406	        vexel_scene::Stop::Overflow => arithmetic(),
407	    })?;
408	    let mut work = 0;
409	    let mut clips = clone_clip_table(view, control, &mut work)?;
410	    let shapes = view.shapes;
411	    let edges = view.edges;
412	    let transforms = view.transforms;
413	    let selected = view.shape(shape).ok_or_else(|| invalid(0))?;
414	    update_clip_shape(
415	        shapes,
416	        edges,
417	        transforms,
418	        &mut clips,
419	        selected,
420	        update_bounds,
421	        control,
422	        &mut work,
423	    )?;
424	    frame.replace_clips(clips, control)
425	}
