  1	//! Owned clip updates for animated transform owners.
  2	use vexel_geometry::{affine_compose, affine_identity, affine_map_point};
  3	use vexel_scene::{
  4	    Clip, ClipGeometry, Diagnostic, Edge, ErrorKind, EvaluatedFrame, LimitKind, Result, SceneView,
  5	    Shape, ShapeId, TransformFrame, TransformId, WorkControl, WorkKind,
  6	};
  7	
  8	const CLIP_COPY_MAX_BYTES: usize = super::DEFAULT_FRAME_BYTE_BUDGET;
  9	const CLIP_CHAIN_MAX: usize = 128;
 10	const CLIP_OWNER_DEPTH_MAX: usize = 64;
 11	const TRANSFORM_WORK_MAX: usize = 50_000_000;
 12	
 13	fn invalid(offset: usize) -> Diagnostic {
 14	    Diagnostic {
 15	        kind: ErrorKind::InvalidArgument,
 16	        offset,
 17	    }
 18	}
 19	fn limit(kind: LimitKind) -> Diagnostic {
 20	    Diagnostic {
 21	        kind: ErrorKind::Limit(kind),
 22	        offset: 0,
 23	    }
 24	}
 25	fn arithmetic() -> Diagnostic {
 26	    limit(LimitKind::Arithmetic)
 27	}
 28	fn oom() -> Diagnostic {
 29	    Diagnostic {
 30	        kind: ErrorKind::OutOfMemory,
 31	        offset: 0,
 32	    }
 33	}
 34	fn add(a: usize, b: usize) -> Result<usize> {
 35	    a.checked_add(b).ok_or_else(arithmetic)
 36	}
 37	fn bytes<T>(count: usize) -> Result<usize> {
 38	    count
 39	        .checked_mul(std::mem::size_of::<T>())
 40	        .ok_or_else(arithmetic)
 41	}
 42	
 43	fn charge(
 44	    control: &mut dyn WorkControl,
 45	    kind: WorkKind,
 46	    count: usize,
 47	    work: &mut usize,
 48	) -> Result<()> {
 49	    let next = work.checked_add(count).ok_or_else(arithmetic)?;
 50	    if next > TRANSFORM_WORK_MAX {
 51	        *work = TRANSFORM_WORK_MAX;
 52	        return Err(limit(LimitKind::Work));
 53	    }
 54	    let units = u64::try_from(count).map_err(|_| arithmetic())?;
 55	    control.charge(kind, units).map_err(|stop| Diagnostic {
 56	        kind: match stop {
 57	            vexel_scene::Stop::Canceled => ErrorKind::Canceled,
 58	            vexel_scene::Stop::Limit => ErrorKind::Limit(LimitKind::Work),
 59	            vexel_scene::Stop::Overflow => ErrorKind::Limit(LimitKind::Arithmetic),
 60	        },
 61	        offset: 0,
 62	    })?;
 63	    *work = next;
 64	    Ok(())
 65	}
 66	fn clip_inverse(m: vexel_scene::Affine) -> Option<vexel_scene::Affine> {
 67	    let det = m.a * m.d - m.b * m.c;
 68	    if !det.is_finite() || det == 0.0 {
 69	        return None;
 70	    }
 71	    let k = 1.0 / det;
 72	    let out = vexel_scene::Affine {
 73	        a: m.d * k,
 74	        b: -m.b * k,
 75	        c: -m.c * k,
 76	        d: m.a * k,
 77	        e: (m.c * m.f - m.d * m.e) * k,
 78	        f: (m.b * m.e - m.a * m.f) * k,
 79	    };
 80	    vexel_geometry::affine_valid(out).then_some(out)
 81	}
 82	
 83	fn node_product(
 84	    transforms: &[TransformFrame],
 85	    target: TransformId,
 86	    control: &mut dyn WorkControl,
 87	    work: &mut usize,
 88	) -> Result<(vexel_scene::Affine, vexel_scene::Affine)> {
 89	    let mut chain = [None; CLIP_CHAIN_MAX];
 90	    let mut count = 0;
 91	    let mut node = Some(target);
 92	    while let Some(id) = node {
 93	        if count == CLIP_CHAIN_MAX || id.index() >= transforms.len() {
 94	            return Err(invalid(0));
 95	        }
 96	        charge(control, WorkKind::ClipChain, 1, work)?;
 97	        chain[count] = Some(id);
 98	        count += 1;
 99	        node = transforms[id.index()].parent;
100	    }
101	    let mut full = affine_identity();
102	    let mut before_suffix = affine_identity();
103	    while count != 0 {
104	        count -= 1;
105	        let id = chain[count].ok_or_else(|| invalid(0))?;
106	        let transform = transforms[id.index()];
107	        let local = affine_compose(transform.motion, transform.attribute)
108	            .ok_or_else(|| invalid(transform.source_offset))?;
109	        if id == target {
110	            before_suffix =
111	                affine_compose(full, local).ok_or_else(|| invalid(transform.source_offset))?;
112	        }
113	        let with_suffix = affine_compose(local, transform.suffix)
114	            .ok_or_else(|| invalid(transform.source_offset))?;
115	        full = affine_compose(full, with_suffix).ok_or_else(|| invalid(transform.source_offset))?;
116	    }
117	    Ok((full, before_suffix))
118	}
