120	fn shape_has_node(
121	    shape: &Shape,
122	    transforms: &[TransformFrame],
123	    target: TransformId,
124	    control: &mut dyn WorkControl,
125	    work: &mut usize,
126	) -> Result<bool> {
127	    let mut node = shape.source.transform_node;
128	    let mut depth = 0;
129	    while let Some(id) = node {
130	        if depth >= CLIP_CHAIN_MAX || id.index() >= transforms.len() {
131	            return Err(invalid(shape.source.element.start));
132	        }
133	        charge(control, WorkKind::ClipChain, 1, work)?;
134	        if id == target {
135	            return Ok(true);
136	        }
137	        node = transforms[id.index()].parent;
138	        depth += 1;
139	    }
140	    Ok(false)
141	}
142	
143	fn bounds_for_node(
144	    shapes: &[Shape],
145	    edges: &[Edge],
146	    transforms: &[TransformFrame],
147	    target: TransformId,
148	    inverse: vexel_scene::Affine,
149	    control: &mut dyn WorkControl,
150	    work: &mut usize,
151	) -> Result<[f64; 4]> {
152	    let mut bounds: Option<[f64; 4]> = None;
153	    for shape in shapes {
154	        if !shape_has_node(shape, transforms, target, control, work)? {
155	            continue;
156	        }
157	        let segment = shape
158	            .edges
159	            .slice(edges)
160	            .ok_or_else(|| invalid(shape.source.element.start))?;
161	        for edge in segment {
162	            charge(control, WorkKind::ClipEdge, 1, work)?;
163	            for point in [edge.a, edge.b] {
164	                let local = affine_map_point(inverse, point)
165	                    .ok_or_else(|| invalid(shape.source.element.start))?;
166	                match &mut bounds {
167	                    Some(b) => {
168	                        b[0] = b[0].min(local.x);
169	                        b[1] = b[1].min(local.y);
170	                        b[2] = b[2].max(local.x);
171	                        b[3] = b[3].max(local.y);
172	                    }
173	                    None => bounds = Some([local.x, local.y, local.x, local.y]),
174	                }
175	            }
176	        }
177	    }
178	    bounds.ok_or_else(|| invalid(0))
179	}
