181	fn update_clip_owner(
182	    shapes: &[Shape],
183	    clips: &mut [Clip],
184	    node: TransformId,
185	    full_inverse: vexel_scene::Affine,
186	    before_suffix_inverse: vexel_scene::Affine,
187	    bounds: Option<[f64; 4]>,
188	    control: &mut dyn WorkControl,
189	    work: &mut usize,
190	) -> Result<()> {
191	    for shape in shapes {
192	        charge(control, WorkKind::ClipChain, 1, work)?;
193	        let mut current = shape.clip;
194	        let mut depth = 0;
195	        while let Some(id) = current {
196	            if depth >= CLIP_OWNER_DEPTH_MAX || id.index() >= clips.len() {
197	                return Err(invalid(shape.source.element.start));
198	            }
199	            charge(control, WorkKind::ClipChain, 1, work)?;
200	            let clip = &mut clips[id.index()];
201	            if clip.owner_node == Some(node) {
202	                clip.user_inverse = if clip.owner_before_suffix {
203	                    before_suffix_inverse
204	                } else {
205	                    full_inverse
206	                };
207	                if let Some(b) = bounds {
208	                    if clip.object_bounding_box
209	                        && b.into_iter().all(f64::is_finite)
210	                        && b[2] >= b[0]
211	                        && b[3] >= b[1]
212	                    {
213	                        clip.bounds = b;
214	                    }
215	                }
216	            }
217	            current = clip.parent;
218	            depth += 1;
219	        }
220	    }
221	    Ok(())
222	}
223	
224	fn update_clip_shape(
225	    shapes: &[Shape],
226	    edges: &[Edge],
227	    transforms: &[TransformFrame],
228	    clips: &mut [Clip],
229	    shape: &Shape,
230	    update_bounds: bool,
231	    control: &mut dyn WorkControl,
232	    work: &mut usize,
233	) -> Result<()> {
234	    let mut node = shape.source.transform_node;
235	    let mut depth = 0;
236	    while let Some(id) = node {
237	        if depth >= CLIP_CHAIN_MAX || id.index() >= transforms.len() {
238	            return Err(invalid(shape.source.element.start));
239	        }
240	        let (full, before_suffix) = node_product(transforms, id, control, work)?;
241	        let full_inverse = clip_inverse(full).ok_or_else(|| invalid(shape.source.element.start))?;
242	        let attribute_inverse =
243	            clip_inverse(before_suffix).ok_or_else(|| invalid(shape.source.element.start))?;
244	        let bounds = if update_bounds {
245	            Some(bounds_for_node(
246	                shapes,
247	                edges,
248	                transforms,
249	                id,
250	                full_inverse,
251	                control,
252	                work,
253	            )?)
254	        } else {
255	            None
256	        };
257	        update_clip_owner(
258	            shapes,
259	            clips,
260	            id,
261	            full_inverse,
262	            attribute_inverse,
263	            bounds,
264	            control,
265	            work,
266	        )?;
267	        node = transforms[id.index()].parent;
268	        depth += 1;
269	    }
270	    Ok(())
271	}
