273	fn clone_clip_table(
274	    view: SceneView<'_>,
275	    control: &mut dyn WorkControl,
276	    work: &mut usize,
277	) -> Result<Vec<Clip>> {
278	    let mut estimate = bytes::<Clip>(view.clips.len())?;
279	    for clip in view.clips {
280	        charge(control, WorkKind::ClipChild, 1, work)?;
281	        estimate = add(estimate, bytes::<Edge>(clip.geometry.edges.len())?)?;
282	        estimate = add(
283	            estimate,
284	            bytes::<vexel_scene::ClipChild>(clip.geometry.shapes.len())?,
285	        )?;
286	    }
287	    if estimate > CLIP_COPY_MAX_BYTES {
288	        return Err(limit(LimitKind::Animation));
289	    }
290	    let mut output = Vec::new();
291	    output
292	        .try_reserve_exact(view.clips.len())
293	        .map_err(|_| oom())?;
294	    for source in view.clips {
295	        charge(control, WorkKind::ClipChild, 1, work)?;
296	        let mut edges = Vec::new();
297	        edges
298	            .try_reserve_exact(source.geometry.edges.len())
299	            .map_err(|_| oom())?;
300	        for edge in &source.geometry.edges {
301	            charge(control, WorkKind::ClipEdge, 1, work)?;
302	            edges.push(*edge);
303	        }
304	        let mut shapes = Vec::new();
305	        shapes
306	            .try_reserve_exact(source.geometry.shapes.len())
307	            .map_err(|_| oom())?;
308	        for child in &source.geometry.shapes {
309	            charge(control, WorkKind::ClipChild, 1, work)?;
310	            shapes.push(*child);
311	        }
312	        output.push(Clip {
313	            geometry: ClipGeometry { edges, shapes },
314	            parent: source.parent,
315	            owner_node: source.owner_node,
316	            owner_before_suffix: source.owner_before_suffix,
317	            object_bounding_box: source.object_bounding_box,
318	            bounds: source.bounds,
319	            user_inverse: source.user_inverse,
320	        });
321	    }
322	    let actual = actual_clip_capacity(&output, control, work)?;
323	    if actual > CLIP_COPY_MAX_BYTES {
324	        return Err(limit(LimitKind::Animation));
325	    }
326	    Ok(output)
327	}
328	
329	fn actual_clip_capacity(
330	    clips: &Vec<Clip>,
331	    control: &mut dyn WorkControl,
332	    work: &mut usize,
333	) -> Result<usize> {
334	    let mut total = clips
335	        .capacity()
336	        .checked_mul(std::mem::size_of::<Clip>())
337	        .ok_or_else(arithmetic)?;
338	    for clip in clips {
339	        charge(control, WorkKind::ClipChild, 1, work)?;
340	        let edges = clip
341	            .geometry
342	            .edges
343	            .capacity()
344	            .checked_mul(std::mem::size_of::<Edge>())
345	            .ok_or_else(arithmetic)?;
346	        let shapes = clip
347	            .geometry
348	            .shapes
349	            .capacity()
350	            .checked_mul(std::mem::size_of::<vexel_scene::ClipChild>())
351	            .ok_or_else(arithmetic)?;
352	        total = add(total, add(edges, shapes)?)?;
353	    }
354	    Ok(total)
355	}
