113	static bool shape_transform_product(const svg_shape_document *document,
114	                                    size_t shape, geom_affine *out,
115	                                    size_t *work)
116	{
117	    if (document->shape_sources == NULL || shape >= document->shape_count ||
118	        document->transform_nodes == NULL || out == NULL || work == NULL)
119	        return false;
120	    size_t chain[ANIMATION_TRANSFORM_CHAIN_MAX];
121	    size_t count = 0U;
122	    size_t node_index = document->shape_sources[shape].transform_node;
123	    while (node_index != SVG_SHAPE_NO_TRANSFORM_NODE) {
124	        if (node_index >= document->transform_node_count ||
125	            count == ANIMATION_TRANSFORM_CHAIN_MAX ||
126	            !consume_work(work, 1U)) return false;
127	        chain[count++] = node_index;
128	        node_index = document->transform_nodes[node_index].parent;
129	    }
130	    geom_affine result = geom_affine_identity();
131	    while (count != 0U) {
132	        const svg_shape_transform_frame *node =
133	            &document->transform_nodes[chain[--count]];
134	        geom_affine local, with_motion;
135	        if (!geom_affine_compose(node->attribute, node->suffix, &local) ||
136	            !geom_affine_compose(node->motion, local, &with_motion) ||
137	            !geom_affine_compose(result, with_motion, &result)) return false;
138	    }
139	    *out = result;
140	    return true;
141	}
