148	
149	static bool affine_inverse(geom_affine value, geom_affine *out)
150	{
151	    double determinant = value.a * value.d - value.b * value.c;
152	    if (out == NULL || !isfinite(determinant) || fabs(determinant) < 1.0e-15)
153	        return false;
154	    double inverse = 1.0 / determinant;
155	    *out = (geom_affine){value.d * inverse, -value.b * inverse,
156	        -value.c * inverse, value.a * inverse,
157	        (value.c * value.f - value.d * value.e) * inverse,
158	        (value.b * value.e - value.a * value.f) * inverse};
159	    return geom_affine_valid(*out);
160	}
161	
162	static bool transform_matrix(const svg_anim_track *track,
163	                             const svg_anim_value *value, geom_affine *out)
164	{
165	    double x = value->number[0], y = value->number[1];
166	    if (!isfinite(x) || !isfinite(y) || fabs(x) > 1000000.0 ||
167	        fabs(y) > 1000000.0) return false;
168	    geom_affine matrix = geom_affine_identity();
169	    if (track->transform_type == SVG_ANIM_TRANSFORM_TRANSLATE) {
170	        matrix.e = x;
171	        matrix.f = y;
172	    } else if (track->transform_type == SVG_ANIM_TRANSFORM_SCALE) {
173	        matrix.a = x;
174	        matrix.d = value->number[3] >= 2.0 ? y : x;
175	    } else if (track->transform_type == SVG_ANIM_TRANSFORM_ROTATE) {
176	        double angle = x * 0.017453292519943295769;
177	        double cosine = cos(angle), sine = sin(angle);
178	        if (!isfinite(cosine) || !isfinite(sine)) return false;
179	        matrix = (geom_affine){cosine, sine, -sine, cosine, 0.0, 0.0};
180	        if (value->number[3] >= 3.0) {
181	            geom_affine to_center = geom_affine_identity();
182	            geom_affine from_center = geom_affine_identity();
183	            to_center.e = value->number[1];
184	            to_center.f = value->number[2];
185	            from_center.e = -value->number[1];
186	            from_center.f = -value->number[2];
187	            geom_affine intermediate;
188	            if (!geom_affine_compose(to_center, matrix, &intermediate) ||
189	                !geom_affine_compose(intermediate, from_center, &matrix)) return false;
190	        }
191	    } else {
192	        double angle = x * 0.017453292519943295769;
193	        double tangent = tan(angle);
194	        if (!isfinite(tangent) || fabs(tangent) > 1000000.0) return false;
195	        if (track->transform_type == SVG_ANIM_TRANSFORM_SKEW_X) matrix.c = tangent;
196	        else matrix.b = tangent;
197	    }
198	    *out = matrix;
199	    return geom_affine_valid(matrix);
200	}
