202	static bool apply_matrix_to_shape(svg_shape_document *document, size_t shape,
203	                                  geom_affine matrix, size_t *work)
204	{
205	    size_t start = document->shape_edge_start[shape];
206	    size_t count = document->shape_edge_count[shape];
207	    if (start > document->edge_count || count > document->edge_count - start)
208	        return false;
209	    if (!consume_work(work, count)) return false;
210	    for (size_t index = start; index < start + count; ++index) {
211	        geom_edge *edge = &document->edges[index];
212	        geom_point first, second;
213	        if (!geom_affine_map_point(matrix, edge->a, &first) ||
214	            !geom_affine_map_point(matrix, edge->b, &second)) return false;
215	        edge->a = first;
216	        edge->b = second;
217	    }
218	    geom_affine inverse;
219	    if (document->shape_stroke_inverse != NULL) {
220	        if (!affine_inverse(matrix, &inverse)) return false;
221	        geom_affine composed;
222	        if (!geom_affine_compose(document->shape_stroke_inverse[shape], inverse,
223	                                 &composed)) return false;
224	        document->shape_stroke_inverse[shape] = composed;
225	    }
226	    svg_shape_paint *paint =
227	        svg_shape_paint_for_shape_mutable(document, shape);
228	    if (paint != NULL && paint->kind != SVG_SHAPE_PAINT_SOLID) {
229	        geom_affine composed;
230	        if (!affine_inverse(matrix, &inverse) ||
231	            !geom_affine_compose(paint->user_inverse, inverse,
232	                                 &composed)) return false;
233	        paint->user_inverse = composed;
234	    }
235	    return true;
236	}
