257	static bool bounds_for_shape(const svg_shape_document *document, size_t shape,
258	                             geom_affine world_inverse, double bounds[4],
259	                             size_t *work)
260	{
261	    size_t start = document->shape_edge_start[shape];
262	    size_t count = document->shape_edge_count[shape];
263	    if (start > document->edge_count || count > document->edge_count - start ||
264	        count == 0U) return false;
265	    if (!consume_work(work, count)) return false;
266	    geom_point first_local;
267	    if (!geom_affine_map_point(world_inverse, document->edges[start].a,
268	                               &first_local)) return false;
269	    bounds[0] = bounds[2] = first_local.x;
270	    bounds[1] = bounds[3] = first_local.y;
271	    for (size_t index = start; index < start + count; ++index) {
272	        const geom_point world_points[2] = {document->edges[index].a,
273	                                            document->edges[index].b};
274	        for (size_t point = 0U; point < 2U; ++point) {
275	            geom_point local;
276	            if (!geom_affine_map_point(world_inverse, world_points[point],
277	                                       &local)) return false;
278	            double x = local.x, y = local.y;
279	            if (x < bounds[0]) bounds[0] = x;
280	            if (y < bounds[1]) bounds[1] = y;
281	            if (x > bounds[2]) bounds[2] = x;
282	            if (y > bounds[3]) bounds[3] = y;
283	        }
284	    }
285	    return true;
286	}
