288	static bool refresh_object_paint_bounds(svg_shape_document *document,
289	                                        size_t shape,
290	                                        geom_affine world_transform,
291	                                        size_t *work)
292	{
293	    svg_shape_paint *paint =
294	        svg_shape_paint_for_shape_mutable(document, shape);
295	    if (paint == NULL) return true;
296	    if (!paint->object_bounding_box ||
297	        (paint->kind != SVG_SHAPE_PAINT_LINEAR &&
298	         paint->kind != SVG_SHAPE_PAINT_RADIAL)) return true;
299	    geom_affine inverse;
300	    double bounds[4];
301	    if (!affine_inverse(world_transform, &inverse) ||
302	        !bounds_for_shape(document, shape, inverse, bounds, work) ||
303	        bounds[2] <= bounds[0] || bounds[3] <= bounds[1]) return false;
304	    memcpy(paint->bounds, bounds, sizeof(bounds));
305	    return true;
306	}
307	
308	static bool matrix_for_numeric(const svg_shape_document *document, size_t shape,
309	                               const svg_anim_track *track,
310	                               const svg_anim_value *value,
311	                               geom_affine world_transform,
312	                               geom_affine *world_delta,
313	                               size_t *work)
314	{
315	    if (value->kind != SVG_ANIM_VALUE_NUMBER || !isfinite(value->number[0]) ||
316	        !isfinite(track->base_value.number[0])) return false;
317	    double delta = value->number[0] - track->base_value.number[0];
318	    if (fabs(delta) > 1000000.0) return false;
319	    geom_affine local_matrix = geom_affine_identity();
320	    switch (track->attribute) {
321	    case SVG_ANIM_ATTR_X:
322	    case SVG_ANIM_ATTR_CX: local_matrix.e = delta; break;
323	    case SVG_ANIM_ATTR_Y:
324	    case SVG_ANIM_ATTR_CY: local_matrix.f = delta; break;
325	    case SVG_ANIM_ATTR_WIDTH:
326	    case SVG_ANIM_ATTR_RX:
327	    case SVG_ANIM_ATTR_R: {
328	        double bounds[4];
329	        geom_affine inverse;
330	        if (!(track->base_value.number[0] > 0.0) ||
331	            !affine_inverse(world_transform, &inverse) ||
332	            !bounds_for_shape(document, shape, inverse, bounds, work)) return false;
333	        double scale = value->number[0] / track->base_value.number[0];
334	        if (!isfinite(scale) || scale < 0.0 || scale > 1000000.0) return false;
335	        double center = track->attribute == SVG_ANIM_ATTR_R ?
336	                        (bounds[0] + bounds[2]) * 0.5 : bounds[0];
337	        local_matrix.a = scale;
338	        local_matrix.e = center * (1.0 - scale);
339	        if (track->attribute == SVG_ANIM_ATTR_R) {
340	            double center_y = (bounds[1] + bounds[3]) * 0.5;
341	            local_matrix.d = scale;
342	            local_matrix.f = center_y * (1.0 - scale);
343	        }
344	        break;
345	    }
346	    case SVG_ANIM_ATTR_HEIGHT:
347	    case SVG_ANIM_ATTR_RY: {
348	        double bounds[4];
349	        geom_affine inverse;
350	        if (!(track->base_value.number[0] > 0.0) ||
351	            !affine_inverse(world_transform, &inverse) ||
352	            !bounds_for_shape(document, shape, inverse, bounds, work)) return false;
353	        double scale = value->number[0] / track->base_value.number[0];
354	        if (!isfinite(scale) || scale < 0.0 || scale > 1000000.0) return false;
355	        double center = bounds[1];
356	        local_matrix.d = scale;
357	        local_matrix.f = center * (1.0 - scale);
358	        break;
359	    }
360	    default: return false;
361	    }
362	    geom_affine inverse, mapped;
363	    return geom_affine_valid(local_matrix) &&
364	        affine_inverse(world_transform, &inverse) &&
365	        geom_affine_compose(world_transform, local_matrix, &mapped) &&
366	        geom_affine_compose(mapped, inverse, world_delta);
367	}
