369	static bool apply_transform_track(svg_shape_document *document,
370	                                  const svg_anim_track *track,
371	                                  const svg_anim_overlay_item *item,
372	                                  bool *transform_seen,
373	                                  geom_affine *world_transforms,
374	                                  size_t *work)
375	{
376	    if (!item->active) return true;
377	    geom_affine animation = geom_affine_identity();
378	    if (track->kind == SVG_ANIM_KIND_TRANSFORM) {
379	        if (!transform_matrix(track, &item->value, &animation)) return false;
380	    } else if (track->kind == SVG_ANIM_KIND_MOTION) {
381	        if (item->value.kind != SVG_ANIM_VALUE_MOTION) return false;
382	        double angle = item->value.number[2] * 0.017453292519943295769;
383	        if (!isfinite(angle) || !isfinite(item->value.number[0]) ||
384	            !isfinite(item->value.number[1])) return false;
385	        geom_affine rotate = {cos(angle), sin(angle), -sin(angle),
386	                              cos(angle), 0.0, 0.0};
387	        geom_affine translate = {1.0, 0.0, 0.0, 1.0,
388	                                 item->value.number[0], item->value.number[1]};
389	        if (!geom_affine_compose(translate, rotate, &animation)) return false;
390	    } else return false;
391	
392	    bool found = false;
393	    for (size_t node = 0U; node < document->transform_node_count; ++node) {
394	        if (!consume_work(work, 1U)) return false;
395	        svg_shape_transform_frame *target = &document->transform_nodes[node];
396	        if (target->source_offset != track->target_offset) continue;
397	        found = true;
398	        if (track->kind == SVG_ANIM_KIND_TRANSFORM) {
399	            if (track->additive_sum || transform_seen[node]) {
400	                if (!geom_affine_compose(target->attribute, animation,
401	                                         &target->attribute)) return false;
402	            } else target->attribute = animation;
403	            transform_seen[node] = true;
404	        } else if (!geom_affine_compose(target->motion, animation,
405	                                       &target->motion)) return false;
406	    }
407	    if (!found) return true;
408	
409	    for (size_t shape = 0U; shape < document->shape_count; ++shape) {
410	        if (!consume_work(work, 1U)) return false;
411	        size_t target_node = SVG_SHAPE_NO_TRANSFORM_NODE;
412	        if (!shape_target_node(document, shape, track, &target_node, work)) {
413	            if (*work >= ANIMATION_TRANSFORM_WORK_MAX) return false;
414	            continue;
415	        }
416	        bool effect_limited = false;
417	        if (!shape_has_animated_effect_limit(document, shape, work,
418	                                             &effect_limited) ||
419	            effect_limited) return false;
420	        geom_affine next_world, old_inverse, delta;
421	        if (!shape_transform_product(document, shape, &next_world, work) ||
422	            !affine_inverse(world_transforms[shape], &old_inverse) ||
423	            !geom_affine_compose(next_world, old_inverse, &delta) ||
424	            !apply_matrix_to_shape(document, shape, delta, work)) return false;
425	        world_transforms[shape] = next_world;
426	        if (document->has_clips && document->clips != NULL &&
427	            !raster_animation_clips_update(document, shape, true, work,
428	                                          ANIMATION_TRANSFORM_WORK_MAX))
429	            return false;
430	        (void)target_node;
431	    }
432	    return true;
433	}
