435	static bool apply_track(svg_shape_document *document,
436	                        const svg_anim_track *track,
437	                        const svg_anim_overlay_item *item,
438	                        bool *transform_seen,
439	                        geom_affine *world_transforms,
440	                        size_t *work)
441	{
442	    if (!item->active) return true;
443	    if (track->kind == SVG_ANIM_KIND_TRANSFORM ||
444	        track->kind == SVG_ANIM_KIND_MOTION)
445	        return apply_transform_track(document, track, item, transform_seen,
446	                                     world_transforms, work);
447	    bool descendant_found = false;
448	    bool direct_found = false;
449	    for (size_t shape = 0U; shape < document->shape_count; ++shape) {
450	        if (!consume_work(work, 1U)) return false;
451	        bool in_target = shape_in_target(document, shape, track, work);
452	        if (*work >= ANIMATION_TRANSFORM_WORK_MAX) return false;
453	        if (!in_target) continue;
454	        descendant_found = true;
455	        if (track->attribute == SVG_ANIM_ATTR_D) return false;
456	        bool direct_target = shape_is_direct_target(document, shape, track, work);
457	        if (*work >= ANIMATION_TRANSFORM_WORK_MAX) return false;
458	        if (!direct_target) continue;
459	        direct_found = true;
460	        bool handled = false;
461	        if (track->attribute == SVG_ANIM_ATTR_FILL &&
462	            item->value.kind == SVG_ANIM_VALUE_COLOR) {
463	            if (document->colors == NULL) return false;
464	            size_t start = document->shape_edge_start[shape];
465	            size_t count = document->shape_edge_count[shape];
466	            if (start > document->edge_count || count > document->edge_count - start)
467	                return false;
468	            if (!consume_work(work, count)) return false;
469	            for (size_t edge = start; edge < start + count; ++edge)
470	                memcpy(document->colors + edge * 4U, item->value.rgba, 4U);
471	            handled = true;
472	        } else if (track->attribute == SVG_ANIM_ATTR_STROKE &&
473	                   item->value.kind == SVG_ANIM_VALUE_COLOR) {
474	            if (document->strokes == NULL) return false;
475	            memcpy(document->strokes[shape].rgba, item->value.rgba, 4U);
476	            handled = true;
477	        } else if (track->attribute == SVG_ANIM_ATTR_OPACITY ||
478	                   track->attribute == SVG_ANIM_ATTR_FILL_OPACITY) {
479	            if (item->value.kind != SVG_ANIM_VALUE_NUMBER || document->colors == NULL)
480	                return false;
481	            double opacity = item->value.number[0];
482	            scale_unit(&opacity);
483	            size_t start = document->shape_edge_start[shape];
484	            size_t count = document->shape_edge_count[shape];
485	            if (start > document->edge_count || count > document->edge_count - start)
486	                return false;
487	            if (!consume_work(work, count)) return false;
488	            for (size_t edge = start; edge < start + count; ++edge) {
489	                uint8_t *alpha = &document->colors[edge * 4U + 3U];
490	                *alpha = (uint8_t)floor((double)*alpha * opacity + 0.5);
491	            }
492	            if (track->attribute == SVG_ANIM_ATTR_OPACITY && document->strokes != NULL) {
493	                uint8_t *alpha = &document->strokes[shape].rgba[3];
494	                *alpha = (uint8_t)floor((double)*alpha * opacity + 0.5);
495	            }
496	            handled = true;
497	        } else if (track->attribute == SVG_ANIM_ATTR_STROKE_OPACITY) {
498	            if (item->value.kind != SVG_ANIM_VALUE_NUMBER || document->strokes == NULL)
499	                return false;
500	            double opacity = item->value.number[0];
501	            scale_unit(&opacity);
502	            uint8_t *alpha = &document->strokes[shape].rgba[3];
503	            *alpha = (uint8_t)floor((double)*alpha * opacity + 0.5);
504	            handled = true;
505	        } else if (track->attribute == SVG_ANIM_ATTR_STROKE_WIDTH ||
506	                   track->attribute == SVG_ANIM_ATTR_STROKE_DASHOFFSET) {
507	            if (item->value.kind != SVG_ANIM_VALUE_NUMBER || document->strokes == NULL ||
508	                (track->attribute == SVG_ANIM_ATTR_STROKE_WIDTH &&
509	                 item->value.number[0] < 0.0) ||
510	                fabs(item->value.number[0]) > 1000000.0)
511	                return false;
512	            if (track->attribute == SVG_ANIM_ATTR_STROKE_WIDTH)
513	                document->strokes[shape].width = item->value.number[0];
514	            else document->strokes[shape].dash_offset = item->value.number[0];
515	            handled = true;
516	        } else if (track->attribute == SVG_ANIM_ATTR_X ||
517	                   track->attribute == SVG_ANIM_ATTR_Y ||
518	                   track->attribute == SVG_ANIM_ATTR_WIDTH ||
519	                   track->attribute == SVG_ANIM_ATTR_HEIGHT ||
520	                   track->attribute == SVG_ANIM_ATTR_CX ||
521	                   track->attribute == SVG_ANIM_ATTR_CY ||
522	                   track->attribute == SVG_ANIM_ATTR_R ||
523	                   track->attribute == SVG_ANIM_ATTR_RX ||
524	                   track->attribute == SVG_ANIM_ATTR_RY) {
525	            geom_affine matrix;
526	            bool effect_limited = false;
527	            if (!shape_has_animated_effect_limit(document, shape, work,
528	                                                 &effect_limited) ||
529	                effect_limited) return false;
530	            if (!matrix_for_numeric(document, shape, track, &item->value,
531	                                    world_transforms[shape], &matrix, work) ||
532	                (svg_shape_paint_for_shape(document, shape) != NULL &&
533	                 svg_shape_paint_for_shape(document, shape)->kind ==
534	                    SVG_SHAPE_PAINT_PATTERN) ||
535	                !apply_geometry_matrix(document, shape, matrix, work) ||
536	                !refresh_object_paint_bounds(document, shape,
537	                                             world_transforms[shape], work) ||
538	                (document->has_clips && document->clips != NULL &&
539	                 !raster_animation_clips_update(document, shape, true, work,
540	                                                ANIMATION_TRANSFORM_WORK_MAX)))
541	                return false;
542	            handled = true;
543	        }
544	        if (!handled) return false;
545	    }
546	    return !descendant_found || direct_found;
547	}
