 10	#define ANIMATION_CLIP_COPY_MAX_BYTES (64U * 1024U * 1024U)
 11	#define ANIMATION_CLIP_CHAIN_MAX 128U
 12	#define ANIMATION_CLIP_OWNER_DEPTH_MAX 64U
 13	
 14	typedef struct clip_copy_entry {
 15	    const svg_shape_clip *source;
 16	    svg_shape_clip *copy;
 17	} clip_copy_entry;
 18	
 19	static bool checked_bytes(size_t count, size_t stride, size_t *out)
 20	{
 21	    if (count != 0U && stride > SIZE_MAX / count) return false;
 22	    *out = count * stride;
 23	    return true;
 24	}
 25	
 26	static bool reserve_clone_bytes(size_t bytes, size_t *total_bytes,
 27	                                bool *limit)
 28	{
 29	    if (*total_bytes > ANIMATION_CLIP_COPY_MAX_BYTES ||
 30	        bytes > ANIMATION_CLIP_COPY_MAX_BYTES - *total_bytes) {
 31	        *limit = true;
 32	        return false;
 33	    }
 34	    *total_bytes += bytes;
 35	    return true;
 36	}
 37	
 38	static bool hash_capacity(size_t count, size_t *capacity)
 39	{
 40	    if (count > SIZE_MAX / 2U) return false;
 41	    size_t needed = count * 2U;
 42	    size_t result = 8U;
 43	    while (result < needed) {
 44	        if (result > SIZE_MAX / 2U) return false;
 45	        result *= 2U;
 46	    }
 47	    *capacity = result;
 48	    return true;
 49	}
 50	
 51	static size_t pointer_hash(const void *pointer)
 52	{
 53	    uintptr_t value = (uintptr_t)pointer;
 54	    value ^= value >> 17U;
 55	    value *= (uintptr_t)0xed5ad4bbU;
 56	    value ^= value >> 11U;
 57	    value *= (uintptr_t)0xac4c1b51U;
 58	    value ^= value >> 15U;
 59	    return (size_t)value;
 60	}
