 62	void raster_animation_clips_release(const svg_shape_document *source,
 63	                                    svg_shape_document *evaluated)
 64	{
 65	    if (source == NULL || evaluated == NULL ||
 66	        evaluated->clips == source->clips) return;
 67	    for (size_t shape = 0U; shape < evaluated->shape_count; ++shape)
 68	        svg_clip_destroy(evaluated->clips == NULL ? NULL :
 69	                         evaluated->clips[shape]);
 70	    free(evaluated->clips);
 71	    evaluated->clips = source->clips;
 72	}
