135	static bool add_work(size_t amount, size_t *work, size_t work_limit)
136	{
137	    if (work == NULL || *work >= work_limit || amount > work_limit - *work) {
138	        if (work != NULL) *work = work_limit;
139	        return false;
140	    }
141	    *work += amount;
142	    return true;
143	}
