145	static bool affine_inverse(geom_affine value, geom_affine *out)
146	{
147	    double determinant = value.a * value.d - value.b * value.c;
148	    if (out == NULL || !isfinite(determinant) || determinant == 0.0)
149	        return false;
150	    double inverse = 1.0 / determinant;
151	    *out = (geom_affine){value.d * inverse, -value.b * inverse,
152	        -value.c * inverse, value.a * inverse,
153	        (value.c * value.f - value.d * value.e) * inverse,
154	        (value.b * value.e - value.a * value.f) * inverse};
155	    return geom_affine_valid(*out);
156	}
