191	static bool shape_has_node(const svg_shape_document *document, size_t shape,
192	                           size_t target, size_t *work, size_t work_limit,
193	                           bool *found)
194	{
195	    if (document->shape_sources == NULL || shape >= document->shape_count)
196	        return false;
197	    size_t node = document->shape_sources[shape].transform_node;
198	    size_t visits = 0U;
199	    *found = false;
200	    while (node != SVG_SHAPE_NO_TRANSFORM_NODE) {
201	        if (node >= document->transform_node_count ||
202	            visits++ >= ANIMATION_CLIP_CHAIN_MAX ||
203	            !add_work(1U, work, work_limit)) return false;
204	        if (node == target) {
205	            *found = true;
206	            return true;
207	        }
208	        node = document->transform_nodes[node].parent;
209	    }
210	    return true;
211	}
