213	static bool bounds_for_node(const svg_shape_document *document, size_t node,
214	                            geom_affine inverse, double bounds[4],
215	                            size_t *work, size_t work_limit)
216	{
217	    bool have_point = false;
218	    for (size_t shape = 0U; shape < document->shape_count; ++shape) {
219	        bool contained = false;
220	        if (!shape_has_node(document, shape, node, work, work_limit,
221	                            &contained)) return false;
222	        if (!contained) continue;
223	        size_t first = document->shape_edge_start[shape];
224	        size_t count = document->shape_edge_count[shape];
225	        if (first > document->edge_count || count > document->edge_count - first)
226	            return false;
227	        for (size_t edge = first; edge < first + count; ++edge) {
228	            if (!add_work(1U, work, work_limit)) return false;
229	            geom_point points[2] = {document->edges[edge].a,
230	                                    document->edges[edge].b};
231	            for (size_t point = 0U; point < 2U; ++point) {
232	                geom_point local;
233	                if (!geom_affine_map_point(inverse, points[point], &local))
234	                    return false;
235	                if (!have_point) {
236	                    bounds[0] = bounds[2] = local.x;
237	                    bounds[1] = bounds[3] = local.y;
238	                    have_point = true;
239	                } else {
240	                    if (local.x < bounds[0]) bounds[0] = local.x;
241	                    if (local.y < bounds[1]) bounds[1] = local.y;
242	                    if (local.x > bounds[2]) bounds[2] = local.x;
243	                    if (local.y > bounds[3]) bounds[3] = local.y;
244	                }
245	            }
246	        }
247	    }
248	    return have_point;
249	}
