251	static bool update_clip_owner(svg_shape_document *document, size_t node,
252	                              geom_affine full_inverse,
253	                              geom_affine attribute_inverse,
254	                              const double *bounds, size_t *work,
255	                              size_t work_limit)
256	{
257	    for (size_t shape = 0U; shape < document->shape_count; ++shape) {
258	        if (!add_work(ANIMATION_CLIP_OWNER_DEPTH_MAX, work, work_limit))
259	            return false;
260	        svg_clip_update_owner(document->clips[shape], node, full_inverse,
261	                              attribute_inverse, bounds);
262	    }
263	    return true;
264	}
