266	bool raster_animation_clips_update(svg_shape_document *document, size_t shape,
267	                                   bool update_bounds, size_t *work,
268	                                   size_t work_limit)
269	{
270	    if (document == NULL || document->clips == NULL ||
271	        document->shape_sources == NULL || shape >= document->shape_count ||
272	        document->transform_nodes == NULL || work == NULL) return false;
273	    size_t node = document->shape_sources[shape].transform_node;
274	    size_t depth = 0U;
275	    while (node != SVG_SHAPE_NO_TRANSFORM_NODE) {
276	        if (node >= document->transform_node_count ||
277	            depth++ >= ANIMATION_CLIP_CHAIN_MAX) return false;
278	        geom_affine full, attribute, full_inverse, attribute_inverse;
279	        if (!node_product(document, node, &full, &attribute, work,
280	                          work_limit) ||
281	            !geom_affine_valid(full) || !geom_affine_valid(attribute))
282	            return false;
283	        double bounds[4];
284	        const double *updated_bounds = NULL;
285	        if (update_bounds) {
286	            if (!affine_inverse(full, &full_inverse) ||
287	                !affine_inverse(attribute, &attribute_inverse) ||
288	                !bounds_for_node(document, node, full_inverse, bounds, work,
289	                                 work_limit)) return false;
290	            updated_bounds = bounds;
291	        } else if (!affine_inverse(full, &full_inverse) ||
292	                   !affine_inverse(attribute, &attribute_inverse)) {
293	            return false;
294	        }
295	        if (!update_clip_owner(document, node, full_inverse,
296	                               attribute_inverse, updated_bounds, work,
297	                               work_limit)) return false;
298	        node = document->transform_nodes[node].parent;
299	    }
300	    return true;
301	}

   250	    Ok(())
