   253	/// Evaluate parsed overlays into a borrowed scene frame with owned changed tables.
   254	pub fn evaluate_frame<'a>(
   255	    view: SceneView<'a>,
   256	    time_seconds: f64,
   257	    control: &mut dyn WorkControl,
   258	) -> Result<EvaluatedFrame<'a>> {
