   262	/// Evaluate a frame using the caller's configured budget for all published
   263	/// frame-owned tables, including old-plus-new clip replacement overlap.
   264	pub fn evaluate_frame_with_budget<'a>(
   265	    view: SceneView<'a>,
   266	    time_seconds: f64,
   267	    byte_budget: usize,
   268	    control: &mut dyn WorkControl,
   269	) -> Result<EvaluatedFrame<'a>> {
   270	    if byte_budget == usize::MAX {
   271	        return Err(limit(LimitKind::ReservedBytes));
   272	    }
   273	    let overlay =
   274	        evaluate_view_controlled(view.animation(), time_seconds, control).map_err(|e| match e {
   275	            EvaluationError::InvalidTime => invalid(0),
   276	            EvaluationError::InvalidTrack => diag(ErrorKind::Unsupported, 0),
   277	            EvaluationError::OutOfMemory => oom(),
   278	            EvaluationError::Canceled => diag(ErrorKind::Canceled, 0),
   279	            EvaluationError::Limit => limit(LimitKind::Work),
   280	            EvaluationError::Overflow => arithmetic(),
   281	        })?;
   282	    let mut builder = FrameBuilder::new(view, byte_budget)?;
   283	    if !overlay.items.iter().any(|item| item.active) {
   284	        return builder.finish(control);
   285	    }
   286	    let mut work = 0usize;
   287	    let mut transforms = copy_table(view.transforms, control)?;
   288	    let mut transform_seen = Vec::new();
   289	    transform_seen
   290	        .try_reserve_exact(view.transforms.len())
   291	        .map_err(|_| oom())?;
   292	    transform_seen.resize(view.transforms.len(), false);
   293	    let mut world = Vec::new();
   294	    world
   295	        .try_reserve_exact(view.shapes.len())
   296	        .map_err(|_| oom())?;
   297	    for shape in view.shapes {
   298	        world.push(product(view.transforms, shape, control, &mut work)?);
   299	    }
   300	    let mut edges = copy_table(view.edges, control)?;
   301	    let mut colors = copy_table(view.edge_colors, control)?;
   302	    let mut shapes = copy_table(view.shapes, control)?;
   303	    let mut fills = copy_table(view.fill_paints, control)?;
   304	    let mut strokes = copy_table(view.stroke_paints, control)?;
   305	    let mut changed_edges = false;
   306	    let mut changed_colors = false;
   307	    let mut changed_shapes = false;
   308	    let mut changed_fills = false;
   309	    let mut changed_strokes = false;
   310	    let has_clip_updates = !view.clips.is_empty()
   311	        && overlay.items.iter().any(|item| {
   312	            item.active
   313	                && view
   314	                    .animation()
   315	                    .tracks
   316	                    .get(item.track_index)
   317	                    .is_some_and(|track| changes_clips(track, *item))
   318	        });
   319	    let mut clip_shape_flags = Vec::new();
   320	    let mut clips = if !has_clip_updates {
   321	        None
   322	    } else {
   323	        Some(clips::clone_clips_for_overlay(view, control)?)
   324	    };
   325	    if has_clip_updates {
   326	        clip_shape_flags
   327	            .try_reserve_exact(view.shapes.len())
   328	            .map_err(|_| oom())?;
   329	        clip_shape_flags.resize(view.shapes.len(), false);
   330	    }
   331	    for item in &overlay.items {
   332	        if !item.active {
   333	            continue;
   334	        }
   335	        charge(control, 1)?;
   336	        work = work.checked_add(1).ok_or_else(arithmetic)?;
   337	        if work > WORK_MAX {
   338	            return Err(limit(LimitKind::Work));
   339	        }
   340	        let track = view
   341	            .animation()
   342	            .tracks
   343	            .get(item.track_index)
   344	            .ok_or_else(|| invalid(0))?;
   345	        match track.kind {
   346	            Kind::Transform | Kind::Motion => {
   347	                let anim = if track.kind == Kind::Transform {
   348	                    transform_value(track, item.value)
   349	                        .ok_or_else(|| diag(ErrorKind::Unsupported, track.element.offset))?
   350	                } else if item.value.kind == ValueKind::Motion {
   351	                    let (s, c) = (item.value.number[2] * 0.017453292519943295769).sin_cos();
   352	                    Affine {
   353	                        a: c,
   354	                        b: s,
   355	                        c: -s,
   356	                        d: c,
   357	                        e: item.value.number[0],
   358	                        f: item.value.number[1],
   359	                    }
   360	                } else {
   361	                    return Err(diag(ErrorKind::Unsupported, track.element.offset));
   362	                };
   363	                let mut found = false;
   364	                for (i, node) in transforms.iter_mut().enumerate() {
   365	                    charge(control, 1)?;
   366	                    count_work(&mut work, 1)?;
   367	                    if node.source_offset != track.target.offset {
   368	                        continue;
   369	                    }
   370	                    found = true;
   371	                    if track.kind == Kind::Motion {
   372	                        node.motion = affine_compose(node.motion, anim)
   373	                            .ok_or_else(|| invalid(track.element.offset))?;
   374	                    } else if track.additive_sum || transform_seen[i] {
   375	                        node.attribute = affine_compose(node.attribute, anim)
   376	                            .ok_or_else(|| invalid(track.element.offset))?;
   377	                    } else {
   378	                        node.attribute = anim;
   379	                    }
   380	                    transform_seen[i] = true;
   381	                }
   382	                if found {
   383	                    for si in 0..shapes.len() {
   384	                        let shape = shapes[si];
   385	                        charge(control, 1)?;
   386	                        count_work(&mut work, 1)?;
   387	                        let mut n = shape.source.transform_node;
   388	                        let mut has = false;
   389	                        let mut depth = 0;
   390	                        while let Some(id) = n {
   391	                            if depth >= CHAIN_MAX || id.index() >= transforms.len() {
   392	                                return Err(invalid(track.element.offset));
   393	                            }
   394	                            charge(control, 1)?;
   395	                            count_work(&mut work, 1)?;
   396	                            if transforms[id.index()].source_offset == track.target.offset {
   397	                                has = true;
   398	                                break;
   399	                            }
   400	                            n = transforms[id.index()].parent;
   401	                            depth += 1;
   402	                        }
   403	                        if !has {
   404	                            continue;
   405	                        }
   406	                        if has_effect(view, si, control, &mut work)? {
   407	                            return Err(diag(ErrorKind::Unsupported, track.element.offset));
   408	                        }
   409	                        let next = product(&transforms, &shape, control, &mut work)?;
   410	                        let delta = affine_compose(
   411	                            next,
   412	                            inverse(world[si], 1e-15)
   413	                                .ok_or_else(|| invalid(track.element.offset))?,
   414	                        )
   415	                        .ok_or_else(|| invalid(track.element.offset))?;
   416	                        map_shape_edges(view, &shape, delta, &mut edges, control, &mut work)?;
   417	                        changed_edges = true;
   418	                        world[si] = next;
   419	                        let mut updated = shape;
   420	                        updated.stroke_inverse = affine_compose(
   421	                            updated.stroke_inverse,
   422	                            inverse(delta, 1e-15).ok_or_else(|| invalid(track.element.offset))?,
   423	                        )
   424	                        .ok_or_else(|| invalid(track.element.offset))?;
   425	                        if let Some(index) = updated.fill_paint {
   426	                            if let Some(p) = fills.get_mut(index) {
   427	                                if p.kind != PaintKind::Solid {
   428	                                    p.user_inverse = affine_compose(
   429	                                        p.user_inverse,
   430	                                        inverse(delta, 1e-15).ok_or_else(|| invalid(0))?,
   431	                                    )
   432	                                    .ok_or_else(|| invalid(0))?;
   433	                                    changed_fills = true;
   434	                                }
   435	                            }
   436	                        }
   437	                        if let Some(index) = updated.stroke_paint {
   438	                            if let Some(p) = strokes.get_mut(index) {
   439	                                if p.kind != PaintKind::Solid {
   440	                                    p.user_inverse = affine_compose(
   441	                                        p.user_inverse,
   442	                                        inverse(delta, 1e-15).ok_or_else(|| invalid(0))?,
   443	                                    )
   444	                                    .ok_or_else(|| invalid(0))?;
   445	                                    changed_strokes = true;
   446	                                }
   447	                            }
   448	                        }
   449	                        shapes[si] = updated;
   450	                        changed_shapes = true;
   451	                        if !clip_shape_flags.is_empty() {
   452	                            clip_shape_flags[si] = true;
   453	                        }
   454	                    }
   455	                }
   456	            }
   457	            _ => apply_value(
   458	                view,
   459	                track,
   460	                *item,
   461	                &mut edges,
   462	                &mut colors,
   463	                &mut shapes,
   464	                &mut fills,
   465	                &mut strokes,
   466	                &world,
   467	                control,
   468	                &mut work,
   469	                &mut changed_edges,
   470	                &mut changed_colors,
   471	                &mut changed_shapes,
   472	                &mut changed_fills,
   473	                &mut changed_strokes,
   474	                &mut clip_shape_flags,
   475	            )?,
   476	        }
   477	        if let Some(clip_table) = clips.as_mut() {
   478	            for si in 0..clip_shape_flags.len() {
   479	                if clip_shape_flags[si] {
   480	                    clips::update_clip_table_for_shape(
   481	                        &transforms,
   482	                        &shapes,
   483	                        &edges,
   484	                        clip_table,
   485	                        si,
   486	                        true,
   487	                        control,
   488	                        &mut work,
   489	                    )?;
   490	                    clip_shape_flags[si] = false;
   491	                }
   492	            }
   493	        }
   494	    }
   495	    if changed_edges {
   496	        builder.replace_edges(edges, control)?;
   497	    }
   498	    if changed_colors {
   499	        builder.replace_colors(colors, control)?;
   500	    }
   501	    if changed_shapes {
   502	        for (idx, value) in shapes.iter().enumerate() {
   503	            let id = view.shape_id(idx).ok_or_else(|| invalid(0))?;
   504	            if view.shapes.get(idx) != Some(value) {
   505	                builder.set_shape(id, *value, control)?;
   506	            }
   507	        }
   508	    }
   509	    if changed_fills {
   510	        for (i, p) in fills.into_iter().enumerate() {
   511	            if view.fill_paints.get(i) != Some(&p) {
   512	                builder.set_fill_paint(i, p, control)?;
   513	            }
   514	        }
   515	    }
   516	    if changed_strokes {
   517	        for (i, p) in strokes.into_iter().enumerate() {
   518	            if view.stroke_paints.get(i) != Some(&p) {
   519	                builder.set_stroke_paint(i, p, control)?;
   520	            }
   521	        }
   522	    }
   523	    for (i, t) in transforms.into_iter().enumerate() {
   524	        if view.transforms.get(i) != Some(&t) {
   525	            let id = view.transform_id(i).ok_or_else(|| invalid(0))?;
   526	            builder.set_transform(id, t, control)?;
   527	        }
   528	    }
   529	    let mut frame = builder.finish(control)?;
   530	    if let Some(clip_table) = clips {
   531	        frame.replace_clips(clip_table, control)?;
   532	    }
   533	    Ok(frame)
   534	}
