 42	    /// Publish a complete clip update only after validating every replacement.
 43	    /// Old owned clips remain live during validation and admission; the original
 44	    /// configured frame budget includes that overlap. Base data never changes.
 45	    pub fn replace_clips(
 46	        &mut self,
 47	        values: Vec<Clip>,
 48	        control: &mut dyn WorkControl,
 49	    ) -> Result<()> {
 50	        control.checkpoint().map_err(stopped)?;
 51	        if values.len() != self.base.clips.len() {
 52	            return Err(invalid(0));
 53	        }
 54	        let view = self.view();
 55	        for (index, clip) in values.iter().enumerate() {
 56	            control.charge(WorkKind::ClipChild, 1).map_err(stopped)?;
 57	            if clip.parent != self.base.clips[index].parent {
 58	                return Err(invalid(0));
 59	            }
 60	            crate::validate::clip_view(view, clip, control)?;
 61	        }
 62	        let new = clip_bytes(&values, control)?;
 63	        if new > 64 * 1024 * 1024 {
 64	            return Err(limit(LimitKind::Animation));
 65	        }
 66	        let old = if let Some(clips) = &self.clips {
 67	            clip_bytes(clips, control)?
 68	        } else {
 69	            0
 70	        };
 71	        let overlap = add(self.stats.live_bytes, new)?;
 72	        if overlap > self.byte_limit {
 73	            return Err(limit(LimitKind::ReservedBytes));
 74	        }
 75	        let live = add(
 76	            self.stats
 77	                .live_bytes
 78	                .checked_sub(old)
 79	                .ok_or_else(arithmetic)?,
 80	            new,
 81	        )?;
 82	        let history = add(self.stats.total_allocated_bytes, new)?;
 83	        let allocations = self
 84	            .stats
 85	            .allocation_count
 86	            .checked_add(usize::from(new != 0))
 87	            .ok_or_else(arithmetic)?;
 88	        control.checkpoint().map_err(stopped)?;
 89	        self.clips = Some(values);
 90	        self.stats.live_bytes = live;
 91	        self.stats.peak_live_bytes = self.stats.peak_live_bytes.max(overlap);
 92	        self.stats.total_allocated_bytes = history;
 93	        self.stats.allocation_count = allocations;
 94	        Ok(())
 95	    }
 96	}
