317	        let new = add(
318	            bytes(&value.geometry.edges)?,
319	            bytes(&value.geometry.shapes)?,
320	        )?;
321	        if let Some(clips) = &self.frame.clips {
322	            let old = add(
323	                bytes(&clips[id.index()].geometry.edges)?,
324	                bytes(&clips[id.index()].geometry.shapes)?,
325	            )?;
326	            let size = clip_bytes(clips, control)?;
327	            if add(size - old, new)? > 64 * 1024 * 1024 {
328	                return Err(limit(LimitKind::Animation));
329	            }
330	            self.incoming(new, old)?;
331	            self.frame.clips.as_mut().ok_or_else(|| invalid(0))?[id.index()] = value;
332	            return Ok(());
333	        }
334	        let before = self.frame.stats.live_bytes;
335	        let result = self.copy_clips(id, value, new, control);
336	        match result {
337	            Ok(values) => {
338	                self.frame.clips = Some(values);
