347	    fn copy_clips(
348	        &mut self,
349	        id: ClipId,
350	        value: Clip,
351	        nested: usize,
352	        control: &mut dyn WorkControl,
353	    ) -> Result<Vec<Clip>> {
354	        let mut result = Vec::new();
355	        let count = self.frame.base.clips.len();
356	        let minimum = count
357	            .checked_mul(std::mem::size_of::<Clip>())
358	            .ok_or_else(arithmetic)?;
359	        if add(self.frame.stats.live_bytes, add(minimum, nested)?)? > self.byte_limit {
360	            return Err(limit(LimitKind::ReservedBytes));
361	        }
362	        result.try_reserve_exact(count).map_err(|_| Diagnostic {
363	            kind: ErrorKind::OutOfMemory,
364	            offset: 0,
365	        })?;
366	        self.incoming(add(bytes(&result)?, nested)?, 0)?;
367	        let mut replacement = Some(value);
368	        for (index, source) in self.frame.base.clips.iter().enumerate() {
369	            control.charge(WorkKind::ClipChild, 1).map_err(stopped)?;
370	            if index == id.index() {
371	                result.push(replacement.take().ok_or_else(|| invalid(0))?);
372	            } else {
373	                let edges = self.copy(&source.geometry.edges, control)?;
374	                let shapes = self.copy(&source.geometry.shapes, control)?;
375	                result.push(Clip {
376	                    geometry: ClipGeometry { edges, shapes },
377	                    parent: source.parent,
378	                    owner_node: source.owner_node,
379	                    owner_before_suffix: source.owner_before_suffix,
380	                    object_bounding_box: source.object_bounding_box,
381	                    bounds: source.bounds,
382	                    user_inverse: source.user_inverse,
383	                });
384	            }
385	        }
386	        if clip_bytes(&result, control)? > 64 * 1024 * 1024 {
387	            return Err(limit(LimitKind::Animation));
388	        }
389	        Ok(result)
390	    }
391	    pub fn finish(self, control: &mut dyn WorkControl) -> Result<EvaluatedFrame<'a>> {
392	        control.checkpoint().map_err(stopped)?;
393	        let view = self.frame.view();
394	        for shape in view.shapes {
395	            crate::validate::shape_attributes_view(view, shape, control)?;
396	        }
397	        for paint in view.fill_paints.iter().chain(view.stroke_paints) {
398	            crate::validate::paint_view(view, paint, control)?;
399	        }
400	        for clip in view.clips {
401	            crate::validate::clip_view(view, clip, control)?;
402	        }
403	        let measured = self.frame.owned_bytes(control)?;
404	        if measured != self.frame.stats.live_bytes {
405	            return Err(invalid(0));
406	        }
407	        Ok(self.frame)
408	    }
