 41	macro_rules! room {
 42	    ($self:ident,$index:expr,$field:ident,$extra:expr,$cap:expr,$pending:expr) => {{
 43	        let pending = $pending;
 44	        let current = add($self.stats.live_bytes, pending)?;
 45	        let available = $self
 46	            .limits
 47	            .reserved_bytes
 48	            .checked_sub(current)
 49	            .ok_or_else(|| limit(LimitKind::ReservedBytes))?;
 50	        // Check all counters before the mutating reserve can transfer old values.
 51	        let history_room = usize::MAX - $self.stats.total_allocated_bytes;
 52	        let available = available.min(history_room);
 53	        if $self.stats.allocation_count == usize::MAX {
 54	            return Err(arithmetic());
 55	        }
 56	        let (new, old) = reserve(&mut $self.scenes[$index].$field, $extra, $cap, available)?;
 57	        if new != 0 {
 58	            $self.stats.peak_live_bytes = $self.stats.peak_live_bytes.max(add(current, new)?);
 59	            $self.stats.total_allocated_bytes = add($self.stats.total_allocated_bytes, new)?;
 60	            $self.stats.allocation_count += 1;
 61	            $self.stats.live_bytes = add($self.stats.live_bytes - old, new)?;
 62	        }
 63	    }};
 64	}
