  8	struct Control {
  9	    canceled: AtomicBool,
 10	    work: u64,
 11	    limit: u64,
 12	}
 13	impl Control {
 14	    fn new(limit: u64) -> Self {
 15	        Self {
 16	            canceled: AtomicBool::new(false),
 17	            work: 0,
 18	            limit,
 19	        }
 20	    }
 21	}
 22	impl WorkControl for Control {
 23	    fn charge(&mut self, _: WorkKind, units: u64) -> Result<(), Stop> {
 24	        if self.canceled.load(Ordering::Acquire) {
 25	            return Err(Stop::Canceled);
 26	        }
 27	        let next = self.work.checked_add(units).ok_or(Stop::Overflow)?;
 28	        if next > self.limit {
 29	            return Err(Stop::Limit);
 30	        }
 31	        self.work = next;
 32	        Ok(())
 33	    }
 34	    fn checkpoint(&mut self) -> Result<(), Stop> {
 35	        if self.canceled.load(Ordering::Acquire) {
 36	            Err(Stop::Canceled)
 37	        } else {
 38	            Ok(())
 39	        }
 40	    }
 41	}
